if (! is_dir(resource_path('views/mail'))) {
    mkdir(resource_path('views/mail'), 0700, true);
}
file_put_contents(resource_path('views/mail/simple.blade.php'), 'Receipt');
class SimpleMail extends Illuminate\Mail\Mailable
{
    use Illuminate\Bus\Queueable;
    use Illuminate\Queue\SerializesModels;

    public function envelope(): Illuminate\Mail\Mailables\Envelope
    {
        return new Illuminate\Mail\Mailables\Envelope(subject: 'Receipt');
    }

    public function content(): Illuminate\Mail\Mailables\Content
    {
        return new Illuminate\Mail\Mailables\Content(view: 'mail.simple');
    }
}
Illuminate\Support\Facades\Schema::create('members', function ($t) {
    $t->id();
    $t->string('name');
    $t->string('email');
    $t->boolean('email_notifications')->default(false);
});
Illuminate\Support\Facades\Schema::create('notifications', function ($t) {
    $t->uuid('id')->primary();
    $t->string('type');
    $t->morphs('notifiable');
    $t->text('data');
    $t->timestamp('read_at')->nullable();
    $t->timestamps();
});
class Member extends Illuminate\Database\Eloquent\Model
{
    use Illuminate\Notifications\Notifiable;

    public $timestamps = false;
    protected $guarded = [];
}
$member = Member::create(['name' => 'Ada', 'email' => 'ada@example.test']);
class DatabaseNotice extends Illuminate\Notifications\Notification
{
    public function via($notifiable): array
    {
        return ['database'];
    }

    public function toDatabase($notifiable): array
    {
        return ['message' => 'Hello'];
    }
}
class PreferenceNotice extends DatabaseNotice
{
    public function via($notifiable): array
    {
        return $notifiable->email_notifications ? ['database', 'mail'] : ['database'];
    }

    public function toMail($notifiable)
    {
        return (new Illuminate\Notifications\Messages\MailMessage())->view('mail.simple');
    }
}
$member->notify(new PreferenceNotice());
echo Illuminate\Support\Facades\DB::table('notifications')->count().':'.app('mailer')->getSymfonyTransport()->messages()->count();
